import numpy as np

# Demo input
demo_input = np.array([
    [0, 0, 0, 3, 0, 0, 0, 0],
    [0, 0, 3, 0, 3, 0, 0, 0],
    [0, 3, 0, 0, 0, 3, 0, 0],
    [3, 0, 0, 0, 0, 0, 3, 0]
])

# Democode
h, w = demo_input.shape

max_row = [0] * w
boundary_cols = set(c for r in range(h) for c in range(w) if demo_input[r,c] == 3)
for c in range(w):
    for r in range(h):
        if demo_input[r, c] == 3:
            max_row[c] = max(max_row[c], r)

print(f"Demo max row per column: {max_row}")

output = demo_input.copy()
for c in range(w):
    if c in boundary_cols:
        for r in range(max_row[c] + 1, h):
            if output[r, c] == 0:
                output[r, c] = 1

print("Col 0:")
for r in range(h):
    print(f"  ({r},{c}): output={output[r,c]}")

print("\nCol 7:")
for r in range(h):
    print(f"  ({r},{c}): output={output[r,c]}")

print("\nFull output:")
print(output)

