import numpy as np

# Demo input
demo_input = np.array([
    [0, 0, 0, 3, 0, 0, 0, 0],
    [0, 0, 3, 0, 3, 0, 0, 0],
    [0, 3, 0, 0, 0, 3, 0, 0],
    [3, 0, 0, 0, 0, 0, 3, 0]
])

# Demo output
demo_output = np.array([
    [0, 0, 0, 3, 0, 0, 0, 0],
    [0, 0, 3, 2, 3, 0, 0, 0],
    [0, 3, 2, 2, 2, 3, 0, 0],
    [3, 2, 2, 2, 2, 2, 3, 0]
])

# Find top boundary row for each column
top_boundary_row = {}
for c in range(8):
    rows_with_3 = [r for r in range(4) if demo_input[r,c] == 3]
    if rows_with_3:
        top_boundary_row[c] = min(rows_with_3)

print("Top boundary row per column:", top_boundary_row)

# Check rule: if top_boundary_row is 0, fill the column from row 1 onwards
print("\nFills from top_boundary_row=0:")
for c, row in top_boundary_row.items():
    if row == 0:
        print(f"  Col {c}: top boundary at row 0, fill {c} in demo_output")
        for r in range(1, 4):
            if demo_output[r,c] == 2:
                print(f"    ({r},{c}) is filled")

# Check the row-between rule: fill cells between left and right boundary on each row
print("\nRow-between fills:")
for r in range(4):
    cols_with_3 = [c for c in range(8) if demo_input[r,c] == 3]
    if len(cols_with_3) >= 2:
        left = min(cols_with_3)
        right = max(cols_with_3)
        for c in range(left + 1, right):
            print(f"  Row {r}: col {c} is between {left} and {right}, filled = {demo_output[r,c] == 2}")
